css:
.cuorisim-container {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
    max-width: 1080px;
    margin: 0 auto;
    padding: 24px;
    color: #2a211c;
    background: linear-gradient(160deg, #f4ede5 0%, #e9ddd0 100%);
    border-radius: 18px;
}

.cuorisim-container * {
    box-sizing: border-box;
}

.cuorisim-header {
    text-align: center;
    padding: 28px 20px 24px;
    background: linear-gradient(135deg, #2b2320 0%, #5a3520 50%, #b5471c 100%);
    color: #fbece1;
    border-radius: 16px;
    margin-bottom: 20px;
    box-shadow: 0 10px 30px rgba(43, 35, 32, 0.35);
}

.cuorisim-header h1 {
    margin: 8px 0 10px;
    font-size: 2.4rem;
    font-weight: 800;
    letter-spacing: -0.5px;
    color: #ffe9d2;
}

.cuorisim-header-tag {
    display: inline-block;
    font-size: 0.74rem;
    text-transform: uppercase;
    letter-spacing: 1.2px;
    font-weight: 700;
    color: #ffd0a6;
    background: rgba(255, 255, 255, 0.10);
    padding: 5px 14px;
    border-radius: 999px;
}

.cuorisim-subtitle {
    margin: 0 auto;
    max-width: 800px;
    font-size: 1rem;
    line-height: 1.58;
    color: #f3ddca;
}

.cuorisim-period-counter {
    display: flex;
    align-items: center;
    gap: 8px;
    flex-wrap: wrap;
    font-size: 0.96rem;
    font-weight: 600;
    color: #5a3520;
    margin-bottom: 18px;
    padding: 6px 4px;
}

.cuorisim-period-counter #currentDay,
.cuorisim-period-counter #maxPeriods {
    font-weight: 800;
    color: #b5471c;
}

.cuorisim-round-name {
    background: #efd9c6;
    color: #8a3b16;
    padding: 3px 12px;
    border-radius: 999px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-left: 4px;
}

.cuorisim-clock {
    margin-left: auto;
    font-size: 0.82rem;
    font-weight: 700;
    color: #8a1414;
    background: #f6dada;
    padding: 4px 12px;
    border-radius: 999px;
}

.cuorisim-status-cards {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 14px;
    margin-bottom: 16px;
}

.cuorisim-status-card {
    background: #fffaf4;
    border-radius: 14px;
    padding: 16px 16px 14px;
    border: 1px solid #e4d3c2;
    box-shadow: 0 4px 14px rgba(90, 53, 32, 0.07);
    border-top: 4px solid #b5471c;
}

.cuorisim-card-idx { border-top-color: #b5471c; }
.cuorisim-card-cog { border-top-color: #2f6f8f; }
.cuorisim-card-aff { border-top-color: #a8327a; }
.cuorisim-card-cred { border-top-color: #b08010; }

.cuorisim-label {
    font-size: 0.72rem;
    text-transform: uppercase;
    letter-spacing: 0.6px;
    font-weight: 700;
    color: #8a7263;
}

.cuorisim-value {
    font-size: 2.6rem;
    font-weight: 800;
    line-height: 1.1;
    margin: 4px 0 2px;
    color: #b5471c;
}

.cuorisim-card-idx .cuorisim-value { color: #b5471c; }
.cuorisim-card-cog .cuorisim-value { color: #2f6f8f; }
.cuorisim-card-aff .cuorisim-value { color: #a8327a; }
.cuorisim-card-cred .cuorisim-value { color: #b08010; }

.cuorisim-sublabel {
    font-size: 0.74rem;
    color: #9a8475;
    line-height: 1.35;
}

.cuorisim-idx-fail .cuorisim-value { color: #b21f1f; }
.cuorisim-idx-target .cuorisim-value { color: #1d7a4d; }

.cuorisim-budget-bar {
    display: flex;
    justify-content: space-between;
    align-items: center;
    background: #2b2320;
    color: #f7e6d6;
    padding: 11px 18px;
    border-radius: 12px;
    margin-bottom: 18px;
    font-weight: 700;
    font-size: 0.92rem;
}

.cuorisim-budget-bar #budgetDisplay {
    font-size: 1.05rem;
    letter-spacing: 0.3px;
}

.cuorisim-budget-over #budgetDisplay {
    color: #ff8b6b;
}

.cuorisim-briefing {
    display: flex;
    gap: 14px;
    background: #fffaf4;
    border-left: 5px solid #b5471c;
    border-radius: 12px;
    padding: 16px 18px;
    margin-bottom: 18px;
    box-shadow: 0 4px 14px rgba(90, 53, 32, 0.06);
}

.cuorisim-briefing-icon {
    font-size: 1.9rem;
    line-height: 1;
}

.cuorisim-briefing-title {
    font-weight: 800;
    font-size: 1.1rem;
    color: #8a3b16;
    margin-bottom: 6px;
}

.cuorisim-briefing-text {
    font-size: 0.95rem;
    line-height: 1.58;
    color: #41342c;
}

.cuorisim-briefing-text strong { color: #1d7a4d; }
.cuorisim-briefing-text em { color: #b21f1f; font-style: italic; }

.cuorisim-controls {
    background: #fffaf4;
    border-radius: 14px;
    padding: 20px 22px;
    margin-bottom: 18px;
    border: 1px solid #e4d3c2;
    box-shadow: 0 4px 14px rgba(90, 53, 32, 0.07);
}

.cuorisim-controls h3 {
    margin: 0 0 16px;
    font-size: 1.12rem;
    font-weight: 800;
    color: #8a3b16;
    border-bottom: 2px solid #efe2d4;
    padding-bottom: 8px;
}

.cuorisim-panel label {
    display: block;
    font-weight: 700;
    font-size: 0.92rem;
    color: #4a382d;
    margin: 14px 0 6px;
}

.cuorisim-container select,
.cuorisim-container input[type="number"] {
    width: 100%;
    padding: 10px 12px;
    border: 1px solid #d8c2ac;
    border-radius: 9px;
    font-size: 0.92rem;
    background-color: #fdf7f0;
    color: #2a211c;
    transition: border-color 0.15s, box-shadow 0.15s;
}

.cuorisim-container select:focus,
.cuorisim-container input[type="number"]:focus {
    outline: none;
    border-color: #b5471c;
    box-shadow: 0 0 0 3px rgba(181, 71, 28, 0.16);
}

.cuorisim-container select option {
    background-color: #fffaf4;
    color: #2a211c;
}

.cuorisim-container input[type="range"] {
    width: 100%;
    margin: 8px 0 2px;
    accent-color: #b5471c;
}

.cuorisim-range-readout,
.cuorisim-alloc-readout {
    font-size: 0.88rem;
    font-weight: 700;
    color: #8a3b16;
    margin-top: 4px;
}

.cuorisim-range-readout span:last-child,
.cuorisim-alloc-readout span:nth-child(2) {
    color: #1d7a4d;
    font-weight: 800;
}

.cuorisim-hint {
    font-size: 0.8rem;
    color: #9a8475;
    margin-top: 4px;
    line-height: 1.42;
}

.cuorisim-container .btn {
    margin-top: 18px;
    font-weight: 700;
}

.cuorisim-container .btn-primary {
    background: linear-gradient(135deg, #b5471c 0%, #e0701f 100%);
    border: none;
    padding: 11px 26px;
    border-radius: 9px;
    box-shadow: 0 6px 16px rgba(181, 71, 28, 0.30);
}

.cuorisim-container .btn-primary:hover {
    filter: brightness(1.06);
}

.cuorisim-container .btn-outline-secondary {
    margin-left: 10px;
    border-color: #d8c2ac;
    color: #8a7263;
}

.cuorisim-coach {
    background: #2b2320;
    color: #f5e6d8;
    border-radius: 14px;
    padding: 16px 20px;
    margin-bottom: 18px;
    box-shadow: 0 6px 18px rgba(43, 35, 32, 0.25);
}

.cuorisim-coach-header {
    font-size: 0.78rem;
    text-transform: uppercase;
    letter-spacing: 1px;
    font-weight: 700;
    color: #e8a772;
    margin-bottom: 8px;
}

.cuorisim-coach-body {
    font-size: 0.95rem;
    line-height: 1.58;
}

.cuorisim-coach-body strong { color: #ffd98a; }
.cuorisim-coach-body em { color: #ffb29a; font-style: italic; }

.cuorisim-history,
.cuorisim-chart {
    background: #fffaf4;
    border-radius: 14px;
    padding: 18px 20px;
    margin-bottom: 18px;
    border: 1px solid #e4d3c2;
    box-shadow: 0 4px 14px rgba(90, 53, 32, 0.07);
}

.cuorisim-history h3,
.cuorisim-chart h3 {
    margin: 0 0 14px;
    font-size: 1.08rem;
    font-weight: 800;
    color: #8a3b16;
}

.cuorisim-container table#usfHistoryTable {
    width: 100%;
    font-size: 0.88rem;
    color: #4a382d;
}

.cuorisim-container table#usfHistoryTable th {
    background: #f3e4d5;
    color: #8a3b16;
    font-weight: 700;
    text-transform: uppercase;
    font-size: 0.72rem;
    letter-spacing: 0.4px;
    padding: 8px 10px;
    border-bottom: 2px solid #e4d0bd;
}

.cuorisim-container table#usfHistoryTable td {
    padding: 8px 10px;
    border-bottom: 1px solid #f0e6db;
}

.cuorisim-container table#usfHistoryTable tr:nth-child(even) td {
    background: #fbf3ea;
}

.cuorisim-chart canvas {
    max-width: 100%;
}

@media (max-width: 768px) {
    .cuorisim-container {
        padding: 14px;
    }
    .cuorisim-header h1 {
        font-size: 1.7rem;
    }
    .cuorisim-status-cards {
        grid-template-columns: repeat(2, 1fr);
        gap: 10px;
    }
    .cuorisim-value {
        font-size: 2rem;
    }
    .cuorisim-clock {
        margin-left: 0;
    }
    .cuorisim-period-counter {
        font-size: 0.88rem;
    }
    .cuorisim-budget-bar {
        flex-direction: column;
        gap: 4px;
        align-items: flex-start;
    }
    .cuorisim-container .btn-outline-secondary {
        margin-left: 0;
        margin-top: 8px;
        display: block;
        width: 100%;
    }
}


/* ---- v1.1.0 completion / debrief screen (cuorisim) ---- */
.cuorisim-completion { padding: 8px 4px 4px; }
.cuorisim-cm-head { text-align: center; margin-bottom: 16px; }
.cuorisim-cm-score { font-size: 3.2rem; font-weight: 800; line-height: 1; color: #b0442a; }
.cuorisim-cm-score-max { font-size: 1.2rem; font-weight: 600; color: #c9755f; }
.cuorisim-cm-grade { font-size: 1.2rem; font-weight: 700; margin-top: 6px; color: #3a2a20; }
.cuorisim-cm-badge { display: inline-block; margin-left: 6px; padding: 2px 10px; border-radius: 999px; font-size: 0.78rem; font-weight: 700; vertical-align: middle; }
.cuorisim-cm-yes { background: rgba(150,90,40,0.15); color: #7a4a1f; border: 1px solid rgba(150,90,40,0.5); }
.cuorisim-cm-no { background: rgba(176,68,42,0.12); color: #a5402a; border: 1px solid rgba(176,68,42,0.45); }
.cuorisim-cm-metrics { display: flex; flex-wrap: wrap; gap: 10px; justify-content: center; margin: 12px 0 16px; }
.cuorisim-cm-metric { flex: 1 1 100px; min-width: 90px; background: rgba(176,68,42,0.08); border: 1px solid rgba(176,68,42,0.2); border-radius: 10px; padding: 10px 8px; text-align: center; }
.cuorisim-cm-mv { display: block; font-size: 1.4rem; font-weight: 800; color: #a04226; }
.cuorisim-cm-ml { display: block; font-size: 0.7rem; margin-top: 4px; color: #7a6555; text-transform: uppercase; letter-spacing: 0.03em; }
.cuorisim-cm-insights-title { font-weight: 700; margin: 8px 0 6px; color: #3a2a20; }
.cuorisim-cm-insights { margin: 0; padding-left: 20px; }
.cuorisim-cm-insights li { margin-bottom: 8px; line-height: 1.5; font-size: 0.92rem; color: #4a3628; }

