(function() {
    'use strict';

    class CuoriAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = `Winning Hearts`;
            this.version = `1.1.0`;

            this.ROUNDS = [
                { id: 1, titleKey: `briefing_title_r1`, textKey: `briefing_text_r1`, panelId: `round1Panel`, nameKey: `round_name_r1`, clockKey: `clock_r1` },
                { id: 2, titleKey: `briefing_title_r2`, textKey: `briefing_text_r2`, panelId: `round2Panel`, nameKey: `round_name_r2`, clockKey: `clock_r2` },
                { id: 3, titleKey: `briefing_title_r3`, textKey: `briefing_text_r3`, panelId: `round3Panel`, nameKey: `round_name_r3`, clockKey: `clock_r3` },
                { id: 4, titleKey: `briefing_title_r4`, textKey: `briefing_text_r4`, panelId: `round4Panel`, nameKey: `round_name_r4`, clockKey: `clock_r4` }
            ];

            // Numbers reference card (Forgiatura Emiliana S.p.A.).
            this.START_IDX = 31;        // identification index now (out of 100)
            this.START_COG = 28;        // cognitive identification component
            this.START_AFF = 22;        // affective/relational identification component
            this.START_CRED = 20;       // credibility with a cynical workforce
            this.TARGET_IDX = 60;       // sector norm / board recovery target
            this.PEAK_2021 = 74;        // the firm's own 2021 level
            this.BUDGET_CAP = 6000;     // €6M engagement envelope, in €000s

            // Concept truths.
            this.TRUE_GAP = `both`;
            this.TRUE_ROOT = `breach`;
        }

        // Locale-aware EUR formatter. EN: "EUR2.4M" (€ before, dot decimal). ES: "2,4 M€" (€ after, comma decimal).
        _fmtM(thousands) {
            const millions = thousands / 1000;
            const lang = (window.mySimulation && window.mySimulation.language) ? window.mySimulation.language : `en`;
            const oneDp = Math.round(millions * 10) / 10;
            if (lang === `es`) {
                return oneDp.toFixed(1).replace(`.`, `,`) + ` M€`;
            }
            return `€` + oneDp.toFixed(1) + `M`;
        }

        _idx(ds) {
            return Math.round(0.40 * ds.cog + 0.40 * ds.aff + 0.20 * ds.cred);
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    idx: this.START_IDX,
                    cog: this.START_COG,
                    aff: this.START_AFF,
                    cred: this.START_CRED,
                    budgetUsed: 0,
                    overspent: false,
                    targetMissed: false,
                    idxHistory: [this.START_IDX],
                    cogHistory: [this.START_COG],
                    affHistory: [this.START_AFF],
                    credHistory: [this.START_CRED],
                    coachMessages: [],
                    lastCoach: ``
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                // Seed = a middling / neutral mix. NOT the textbook-correct play.
                state.decisions = {
                    gap: `cognitive`,
                    root: `market`,
                    candor: 50,
                    narr: `spin`,
                    listen: `townhall`,
                    lean: `fiat`,
                    ps: `fullbonus`,
                    rec: `cash`,
                    sup: 500,
                    commit: `overpromise`,
                    seq: `both6`,
                    conv: 60
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            const state = window.mySimulation.state;
            const round = state.currentPeriod || 1;
            const warn = (k) => window.mySimulation.uiManager.showNotification(window.mySimulation.t(k), `warning`);

            if (round === 1) {
                const gap = document.getElementById(`gapInput`);
                const root = document.getElementById(`rootInput`);
                const cd = document.getElementById(`candorInput`);
                if (gap) decisions.gap = gap.value;
                if (root) decisions.root = root.value;
                if (cd) decisions.candor = parseInt(cd.value, 10);
                if (!Number.isFinite(decisions.candor) || decisions.candor < 0 || decisions.candor > 100) {
                    warn(`warn_candor_range`); return false;
                }
            } else if (round === 2) {
                const narr = document.getElementById(`narrInput`);
                const listen = document.getElementById(`listenInput`);
                const lean = document.getElementById(`leanInput`);
                if (narr) decisions.narr = narr.value;
                if (listen) decisions.listen = listen.value;
                if (lean) decisions.lean = lean.value;
            } else if (round === 3) {
                const ps = document.getElementById(`psInput`);
                const rec = document.getElementById(`recInput`);
                const sup = document.getElementById(`supInput`);
                if (ps) decisions.ps = ps.value;
                if (rec) decisions.rec = rec.value;
                if (sup) decisions.sup = parseInt(sup.value, 10);
                if (!Number.isFinite(decisions.sup) || decisions.sup < 0 || decisions.sup > 1500) {
                    warn(`warn_sup_range`); return false;
                }
            } else if (round === 4) {
                const commit = document.getElementById(`commitInput`);
                const seq = document.getElementById(`seqInput`);
                const conv = document.getElementById(`convInput`);
                if (commit) decisions.commit = commit.value;
                if (seq) decisions.seq = seq.value;
                if (conv) decisions.conv = parseInt(conv.value, 10);
                if (!Number.isFinite(decisions.conv) || decisions.conv < 0 || decisions.conv > 100) {
                    warn(`warn_conv_range`); return false;
                }
            }
            return true;
        }

        calculateResults(state) {
            const d = state.decisions;
            const ds = state.domainState;
            const round = state.currentPeriod;

            // Deltas on the two halves of identification (cog, aff) plus credibility (cred),
            // the lens through which a cynical workforce reads sincerity.
            let dcog = 0, daff = 0, dcred = 0, spend = 0;
            let coachKey = `coach_default`;
            let summaryKey = `sum_default`;

            if (round === 1) {
                // Diagnose the identity gap — feed BOTH halves, not one (Common Error 5).
                if (d.gap === this.TRUE_GAP) {
                    dcog += 7; daff += 7; dcred += 4; coachKey = `coach_r1_both`;
                } else if (d.gap === `cognitive`) {
                    dcog += 8; daff -= 3; coachKey = `coach_r1_onesided`;
                } else if (d.gap === `affective`) {
                    daff += 8; dcog -= 3; coachKey = `coach_r1_onesided`;
                } else {
                    dcog -= 4; daff -= 4; dcred -= 3; coachKey = `coach_r1_denial`;
                }

                // Root cause: a breached psychological contract, not the market or the workers.
                if (d.root === this.TRUE_ROOT) {
                    dcog += 4; daff += 4; dcred += 6;
                    if (d.gap === this.TRUE_GAP) coachKey = `coach_r1_sharp`;
                } else if (d.root === `market`) {
                    dcred -= 3; coachKey = `coach_r1_market`;
                } else {
                    dcog -= 5; daff -= 6; dcred -= 6; coachKey = `coach_r1_workers`;
                }

                // Candor: acknowledging the rupture builds credibility; pretending it away corrodes it.
                if (d.candor >= 60) { dcred += 6; daff += 3; }
                else if (d.candor <= 25) { dcred -= 6; daff -= 3; coachKey = `coach_r1_lowcandor`; }

                summaryKey = (d.gap === this.TRUE_GAP && d.root === this.TRUE_ROOT) ? `sum_r1_good` : `sum_r1_weak`;
            } else if (round === 2) {
                // Symbolic & communication strategy (Common Errors 2 & 4).
                switch (d.narr) {
                    case `honest`: dcred += 9; daff += 6; dcog += 3; coachKey = `coach_r2_honest`; break;
                    case `spin`: dcred -= 5; daff -= 3; coachKey = `coach_r2_spin`; break;
                    case `silence`: dcred -= 8; daff -= 5; coachKey = `coach_r2_silence`; break;
                }

                switch (d.listen) {
                    case `tour`: spend += 700; daff += 8; dcred += 6; dcog += 2; coachKey = (d.narr === `honest`) ? `coach_r2_tour` : coachKey; break;
                    case `townhall`: spend += 200; daff += 2; dcred += 1; break;
                    case `memo`: spend += 30; daff -= 2; dcred -= 3; coachKey = `coach_r2_memo`; break;
                }

                switch (d.lean) {
                    case `codesign`: spend += 900; dcog += 9; daff += 3; dcred += 5; break;
                    case `fiat`: spend += 300; dcog += 1; dcred -= 5; daff -= 2; coachKey = `coach_r2_fiat`; break;
                    case `mandate`: spend += 120; dcog -= 3; dcred -= 3; coachKey = `coach_r2_mandate`; break;
                }

                summaryKey = (d.narr === `honest` && d.lean === `codesign` && d.listen !== `memo`) ? `sum_r2_good` : `sum_r2_weak`;
            } else if (round === 3) {
                // Reward & recognition signals within €6M (Common Error 1: leading with money).
                switch (d.ps) {
                    case `trigger`: spend += 2200; daff += 7; dcog += 6; dcred += 6; coachKey = `coach_r3_trigger`; break;
                    case `fullbonus`: spend += 3400; daff += 1; dcred -= 2; coachKey = `coach_r3_money`; break;
                    case `none`: daff -= 3; dcred -= 3; coachKey = `coach_r3_frozen`; break;
                }

                switch (d.rec) {
                    case `craft`: spend += 1100; daff += 7; dcog += 6; dcred += 3; break;
                    case `cash`: spend += 900; daff += 1; dcog -= 2; coachKey = (d.ps === `fullbonus`) ? `coach_r3_money` : coachKey; break;
                    case `none`: daff -= 2; break;
                }

                // Supervisors as identity carriers — real investment (≥€0.9M) equips them.
                spend += d.sup;
                if (d.sup >= 900) { dcog += 6; daff += 4; dcred += 5; }
                else if (d.sup >= 450) { dcog += 3; daff += 2; dcred += 2; }
                else { dcred -= 3; coachKey = (coachKey === `coach_default`) ? `coach_r3_nosup` : coachKey; }

                summaryKey = (d.ps === `trigger` && d.rec === `craft` && d.sup >= 900) ? `sum_r3_good` : (d.ps === `fullbonus` ? `sum_r3_money` : `sum_r3_weak`);
            } else if (round === 4) {
                // Strike ballot & 24-month trajectory (Common Errors 3 & 6: over-promise; wrong sequence).
                switch (d.commit) {
                    case `credible`: dcred += 10; daff += 6; dcog += 3; coachKey = `coach_r4_credible`; break;
                    case `overpromise`: dcred += 3; daff += 3; break; // short-term, then the time-bomb below
                    case `stonewall`: dcred -= 8; daff -= 6; coachKey = `coach_r4_stonewall`; break;
                }

                switch (d.seq) {
                    case `idfirst`: dcog += 7; daff += 6; dcred += 6; coachKey = (d.commit === `credible`) ? `coach_r4_idfirst` : coachKey; break;
                    case `both6`: dcred -= 5; coachKey = `coach_r4_both6`; break;
                    case `ebitfirst`: dcog -= 5; daff -= 8; dcred -= 8; coachKey = `coach_r4_ebitfirst`; break;
                }

                // Conviction nudges both halves.
                dcog += Math.round((d.conv - 60) / 10);
                daff += Math.round((d.conv - 60) / 12);

                // The second-broken-promise time-bomb: over-promising to win the vote collapses
                // credibility once a promise inevitably breaks (Common Error 3).
                if (d.commit === `overpromise`) {
                    dcred -= 14; daff -= 8; dcog -= 3; coachKey = `coach_r4_overpromise`;
                }

                summaryKey = (d.commit === `credible` && d.seq === `idfirst`) ? `sum_r4_good` : (d.commit === `overpromise` ? `sum_r4_overpromise` : `sum_r4_weak`);
            }

            // Budget accounting. Overspending the €6M envelope dampens this round's positive gains
            // (the board pulls the money; gestures land thinner) and is flagged.
            const wouldBe = ds.budgetUsed + spend;
            if (wouldBe > this.BUDGET_CAP) ds.overspent = true;
            ds.budgetUsed = wouldBe;
            const pen = ds.overspent ? 0.6 : 1;
            const apply = (v) => (v > 0 ? v * pen : v);

            ds.cog = Math.max(0, Math.min(100, ds.cog + apply(dcog)));
            ds.aff = Math.max(0, Math.min(100, ds.aff + apply(daff)));
            ds.cred = Math.max(0, Math.min(100, ds.cred + apply(dcred)));
            ds.idx = this._idx(ds);

            ds.idxHistory.push(ds.idx);
            ds.cogHistory.push(Math.round(ds.cog));
            ds.affHistory.push(Math.round(ds.aff));
            ds.credHistory.push(Math.round(ds.cred));

            if (round === this.ROUNDS.length && ds.idx < this.TARGET_IDX) ds.targetMissed = true;

            const coachMsg = window.mySimulation.t(coachKey);
            ds.lastCoach = coachMsg;
            ds.coachMessages.push(coachMsg);
            const coachEl = document.getElementById(`coachText`);
            if (coachEl) coachEl.innerHTML = coachMsg;

            const self = this;
            setTimeout(function() {
                self._updateBriefing({ currentPeriod: state.currentPeriod + 1 });
            }, 500);

            // Expose composite (0-100) to the reporting/grading layer every period
            // (express/results_utils.php::express_resolveDomainScore reads domainState.performance.overallScore).
            ds.performance = { overallScore: this._composite(ds) };

            return {
                period: state.currentPeriod,
                idx: ds.idx,
                cog: Math.round(ds.cog),
                aff: Math.round(ds.aff),
                cred: Math.round(ds.cred),
                budgetUsed: ds.budgetUsed,
                overspent: ds.overspent,
                summary: window.mySimulation.t(summaryKey),
                coach: coachMsg
            };
        }

