                let total = 0;
                const psCost = { trigger: 2200, fullbonus: 3400, none: 0 };
                const recCost = { craft: 1100, cash: 900, none: 0 };
                if (psEl) total += (psCost[psEl.value] || 0);
                if (recEl) total += (recCost[recEl.value] || 0);
                if (supEl) total += (parseInt(supEl.value, 10) || 0);
                const readout = document.getElementById(`r3SpendReadout`);
                if (readout) readout.textContent = self._fmtM(total);
                const bar = document.querySelector(`.cuorisim-alloc-readout`);
                if (bar) bar.style.color = (total + (self._priorSpend() || 0) > self.BUDGET_CAP) ? `#b21f1f` : ``;
            };
            [`psInput`, `recInput`, `supInput`].forEach((id) => {
                const el = document.getElementById(id);
                if (el) el.addEventListener(`input`, recompute);
            });
            recompute();
        }

