        getChartData(state) {
            const ds = state.domainState;
            const t = window.mySimulation ? window.mySimulation.t.bind(window.mySimulation) : (k) => k;
            const labels = ds.idxHistory.map((_, i) => (i === 0 ? t(`chart_start`) : `R` + i));
            return {
                cuoriChart: {
                    labels: labels,
                    datasets: [
                        { data: ds.idxHistory },
