        // Composite (0-100) written to domainState.performance.overallScore each period for the
        // reporting/grading layer. Formula copied VERBATIM from v1.0.0 getPerformanceSummary.
        _composite(ds) {
            const idx = Math.round(ds.idx);
            const cog = Math.round(ds.cog);
            const aff = Math.round(ds.aff);
            const cred = Math.round(ds.cred);
            return Math.max(0, Math.min(100, Math.round(idx * 0.5 + ((cog + aff) / 2) * 0.30 + cred * 0.20)));
        }

        _cl(key, fallback) {
            try {
                const v = (window.mySimulation && typeof window.mySimulation.t === `function`)
                    ? window.mySimulation.t(key) : key;
                return (v && v !== key) ? v : fallback;
            } catch (e) { return fallback; }
        }

        formatCompletionMessage(summary) {
            const T = (window.mySimulation && typeof window.mySimulation.t === `function`)
                ? function(k) { return window.mySimulation.t(k); }
                : function(k) { return k; };
            const s = summary || {};
            const score = (typeof s.overallScore === `number`) ? s.overallScore
                : (typeof s.totalScore === `number` ? s.totalScore
                : (typeof s.composite === `number` ? s.composite : 0));
            const grade = s.performance || (s.performanceKey ? T(s.performanceKey) : ``);
            const met = !!s.met;
            const badge = met
                ? `<span class="cuorisim-cm-badge cuorisim-cm-yes">` + T(`cm_met`) + `</span>`
                : `<span class="cuorisim-cm-badge cuorisim-cm-no">` + T(`cm_notmet`) + `</span>`;
            let failBadge = ``;
            if (s.overspent) failBadge += ` <span class="cuorisim-cm-badge cuorisim-cm-no">` + T(`cm_overspent`) + `</span>`;
            if (s.hitTarget && !s.balanced) failBadge += ` <span class="cuorisim-cm-badge cuorisim-cm-no">` + T(`cm_onesided`) + `</span>`;
            if (!s.hitTarget) failBadge += ` <span class="cuorisim-cm-badge cuorisim-cm-no">` + T(`cm_missed`) + `</span>`;
            const insights = Array.isArray(s.insights) ? s.insights : [];
            const items = insights.map(function(t) { return `<li>` + t + `</li>`; }).join(``);
            const metrics = ``
                + `<div class="cuorisim-cm-metric"><span class="cuorisim-cm-mv">` + Math.round(s.idx || 0) + `</span><span class="cuorisim-cm-ml">` + T(`cm_m_idx`) + `</span></div>`
                + `<div class="cuorisim-cm-metric"><span class="cuorisim-cm-mv">` + Math.round(s.cog || 0) + `</span><span class="cuorisim-cm-ml">` + T(`cm_m_cog`) + `</span></div>`
                + `<div class="cuorisim-cm-metric"><span class="cuorisim-cm-mv">` + Math.round(s.aff || 0) + `</span><span class="cuorisim-cm-ml">` + T(`cm_m_aff`) + `</span></div>`
                + `<div class="cuorisim-cm-metric"><span class="cuorisim-cm-mv">` + Math.round(s.cred || 0) + `</span><span class="cuorisim-cm-ml">` + T(`cm_m_cred`) + `</span></div>`;
            return ``
                + `<div class="cuorisim-completion">`
                +   `<div class="cuorisim-cm-head">`
                +     `<div class="cuorisim-cm-score">` + score + `<span class="cuorisim-cm-score-max">/100</span></div>`
                +     `<div class="cuorisim-cm-grade">` + grade + ` ` + badge + failBadge + `</div>`
                +   `</div>`
                +   `<div class="cuorisim-cm-metrics">` + metrics + `</div>`
                +   `<div class="cuorisim-cm-insights-title">` + T(`cm_debrief`) + `</div>`
                +   `<ul class="cuorisim-cm-insights">` + items + `</ul>`
                + `</div>`;
        }

        getPerformanceSummary(history) {
            if (!history.length) return {};
            const ds = window.mySimulation.state.domainState;
            const idx = Math.round(ds.idx);
            const cog = Math.round(ds.cog);
            const aff = Math.round(ds.aff);
            const cred = Math.round(ds.cred);

            const hitTarget = idx >= this.TARGET_IDX;
            const balanced = Math.abs(cog - aff) <= 14 && Math.min(cog, aff) >= 55;
            const composite = this._composite(ds);

            let performanceKey = `grade_curdled`;
            if (hitTarget && balanced && cred >= 60 && composite >= 75) performanceKey = `grade_restored`;
            else if (hitTarget && balanced) performanceKey = `grade_rebuilding`;
            else if (hitTarget && !balanced) performanceKey = `grade_starved`;
            else if (idx >= this.START_IDX + 12) performanceKey = `grade_moving`;
            const performance = window.mySimulation.t(performanceKey);

            const insights = [];
            if (hitTarget && balanced && cred >= 60) insights.push(window.mySimulation.t(`insight_restored`));
            else if (hitTarget && !balanced) insights.push(window.mySimulation.t(`insight_onesided`));
            else if (hitTarget) insights.push(window.mySimulation.t(`insight_thin`));
            else insights.push(window.mySimulation.t(`insight_short`));

            if (ds.overspent) insights.push(window.mySimulation.t(`insight_overspent`));
            if (cred < 45) insights.push(window.mySimulation.t(`insight_lowcred`));
            if (idx >= this.PEAK_2021) insights.push(window.mySimulation.t(`insight_peak`));
            if (hitTarget && balanced && cred >= 60) insights.push(window.mySimulation.t(`insight_sequence`));

            return {
                idx: idx,
                cog: cog,
                aff: aff,
                cred: cred,
                hitTarget: hitTarget,
                balanced: balanced,
                overspent: ds.overspent,
                composite: composite,
                totalScore: composite,
                overallScore: composite,
                met: (hitTarget && balanced && cred >= 60 && composite >= 75),
                performanceKey: performanceKey,
                performance: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (!results) return null;
            const ds = state.domainState;
            if (ds.overspent) return window.mySimulation.t(`hint_overspent`);
            if (Math.abs(ds.cog - ds.aff) >= 18 && state.currentPeriod >= 2) return window.mySimulation.t(`hint_onesided`);
            if (ds.cred < 35) return window.mySimulation.t(`hint_cred`);
            if (state.currentPeriod >= 3 && ds.idx < 48) return window.mySimulation.t(`hint_behind`);
            if (ds.idx >= this.TARGET_IDX && ds.cred >= 60) return window.mySimulation.t(`hint_strong`);
            return null;
        }

